mapper.select:
SELECT file_id, ref_type, ref_id, ref_id2, ref_id3,
       file_name, file_path,
       file_size, content_type, sort_order, created_by, created_at
FROM tb_file
WHERE ref_type = #{refType} AND ref_id = #{refId}

    AND ref_id2 = #{refId2}
    AND ref_id2 IS NULL


    AND ref_id3 = #{refId3}
    AND ref_id3 IS NULL

ORDER BY sort_order
